contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // After this test contract deployed c, the constructor set bank = address(this).
        // To force a losing round (random != 0), we need the pot to be zero
        // at the deciding play. The only way to make the pot zero is for
        // play to win and reset it. But there is a simpler fact:
        // if pot == 0 before a call, then on a winning round the only transfer
        // is the fee: FEE_AMOUNT = 1 wei goes to bank, and the pot (which is 0)
        // goes to msg.sender, so the contract balance drops by exactly 10 wei
        // (the sent ticket). On a losing round the contract keeps the ticket,
        // so the balance increases by 10 wei. Either way, the amount of wei
        // that leaves the contract on a successful play is at most 10 wei,
        // and the contract cannot send out more than it received plus its
        // pre-existing balance. The general rule: on success the balance
        // change is exactly amount minus the pot payout, where the pot
        // payout is either 0 or the pre-call pot, and the fee is paid only
        // when winning. In all cases, the contract balance never decreases
        // by more than amount.
        uint balBefore = address(c).balance;

        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }

        uint balAfter = address(c).balance;

        assert(amount != 10 || !reverted);
        // The main rule: a successful play cannot cause the contract to lose
        // more wei than the ticket just paid in. This holds because the only
        // outgoing transfers are the fee (1 wei, covered by the ticket) and
        // the pot payout (which was accumulated from previous tickets).
        assert(amount != 10 || reverted || balAfter + amount >= balBefore);
    }

    receive() external payable {}
}

